function syncNativeAdhan(){if(!window.ShamsAndroid?.configureAdhan)return;const p=place(),c=read('basira-calculation',{method:13,school:0}),value=JSON.stringify({enabled:read('shams-azan-enabled',false),latitude:p.latitude,longitude:p.longitude,timezone:p.timezone||'UTC',method:c.method??13,school:c.school??0,locale:lang(),prayers:names.map((_,i)=>!!settings[i]),names:names.map(n=>tr(n))});if(value!==nativeAdhanSignature){window.ShamsAndroid.configureAdhan(value);nativeAdhanSignature=value}}
function paintNativeAdhan(){const box=document.querySelector('#nativeAdhanStatus');if(!box)return;try{const s=JSON.parse(window.ShamsAndroid.adhanStatus());box.textContent=!s.enabled?'':!s.exact||!s.notifications?v16('required'):s.next?v16('ready')+': '+new Date(s.next).toLocaleString(lang(),{timeZone:place().timezone}):s.error?pw('retry'):v16('preparing')}catch{box.textContent=v16('required')}}
