 if(window.ShamsAndroid?.configureAdhan){const notifications=compactNotificationsPage;compactNotificationsPage=function(){return notifications().replace(tr('Xatırlatmalar yalnız tətbiq açıq və brauzer icazəsi verildiyi müddətdə işləyir. Bağlı tətbiq üçün fon bildirişləri dəstəklənmir.'),v16('background')+' '+v16('otherReminders')).replace('onclick="requestNotices()"','onclick="nativeAdhanPermissions()"').replace(tr('Brauzer bildirişlərinə icazə ver'),v16('permission'))};updateWords.masterNote=v16Words.background;const base=azanCard;azanCard=function(){return base().replace('</section>',`<div class="native-adhan-status"><small id="nativeAdhanStatus" role="status"></small><div class="native-adhan-actions"><button class="secondarybtn" onclick="nativeAdhanPermissions()">${v16('permission')}</button><button class="secondarybtn" onclick="nativeAdhanTest()">${v16('test')}</button></div></div></section>`)};checkAzanTime=()=>{};const enable=setAzanEnabled;setAzanEnabled=function(on){enable(on);if(on&&!names.some((_,i)=>settings[i])){names.forEach((_,i)=>settings[i]=true);save('nur-settings',settings)}syncNativeAdhan();if(on)nativeAdhanPermissions();paintNativeAdhan()};setNotice=function(k,v){settings[k]=v;save('nur-settings',settings);syncNativeAdhan();paintNativeAdhan()};setInterval(()=>{syncNativeAdhan();paintNativeAdhan()},1500);syncNativeAdhan();}
