async function drawShamsWordmark(c,x,y,width,color){const img=new Image();img.src='icons/shams-wordmark.png';await img.decode();const mask=document.createElement('canvas');mask.width=img.naturalWidth;mask.height=img.naturalHeight;const m=mask.getContext('2d');m.drawImage(img,0,0);m.globalCompositeOperation='source-in';m.fillStyle=color;m.fillRect(0,0,mask.width,mask.height);c.drawImage(mask,x,y,width,width*mask.height/mask.width)}
